record.field:
for budget in records:
    budget.sudo().write({
        'x_active_precommitment_amount': 0.0,
        'x_odoo_committed_amount': 0.0,
        'x_available_amount': budget.x_budgeted_amount or 0.0,
        'x_last_refresh': datetime.datetime.now(),
        'x_overrun': False,
        'x_overrun_notified': False,
    })

for budget in records:
    bindings = env['x_greenbear.precommitment'].search([('x_budget_id', '=', budget.id)])
    active_amount = 0.0
    order_ids = []
    odoo_amount = 0.0
    for binding in bindings:
        if binding.x_state == 'active':
            active_amount += binding.x_amount or 0.0
        procurement = binding.x_procurement_id
        if procurement:
            for order in procurement.x_purchase_order_ids:
                if order.id not in order_ids and order.state in ['purchase', 'done']:
                    order_ids.append(order.id)
                    posted_invoice_amount = 0.0
                    has_posted_invoice = False
                    for invoice in order.invoice_ids:
                        if invoice.state == 'posted' and invoice.move_type in ['in_invoice', 'in_refund']:
                            has_posted_invoice = True
                            if invoice.move_type == 'in_refund':
                                posted_invoice_amount -= invoice.amount_total or 0.0
                            else:
                                posted_invoice_amount += invoice.amount_total or 0.0
                    if has_posted_invoice:
                        odoo_amount += posted_invoice_amount
                    else:
                        odoo_amount += order.amount_total or 0.0
    available = (budget.x_budgeted_amount or 0.0) - active_amount - odoo_amount
    overrun = available < 0.0
    values = {
        'x_active_precommitment_amount': active_amount,
        'x_odoo_committed_amount': odoo_amount,
        'x_available_amount': available,
        'x_last_refresh': datetime.datetime.now(),
        'x_overrun': overrun,
        'x_overrun_notified': budget.x_overrun_notified if overrun else False,
    }
    if overrun and not budget.x_overrun_notified:
        finance_group = env.ref('greenbear_procurement.group_greenbear_finance')
        finance_user = env['res.users'].sudo().search([
            ('active', '=', True),
            ('all_group_ids', 'in', finance_group.id),
        ], order='id', limit=1)
        if not finance_user:
            finance_user = env.user
        partner_model = env['ir.model'].search([('model', '=', 'res.partner')], limit=1)
        activity_type = env.ref('mail.mail_activity_data_todo')
        env['mail.activity'].sudo().create({
            'activity_type_id': activity_type.id,
            'res_model_id': partner_model.id,
            'res_id': finance_user.partner_id.id,
            'user_id': finance_user.id,
            'summary': 'greenBEAR-Budgetüberschreitung prüfen',
            'note': 'Budget %s: verfügbar %.2f EUR. Bitte Beschaffung und Budgetzuordnung prüfen.' % (budget.x_name, available),
            'date_deadline': datetime.date.today(),
        })
        values['x_overrun_notified'] = True
    budget.sudo().write(values)
    note = 'Budget verfügbar: %.2f EUR' % available
    if overrun:
        note = 'WARNUNG: Budget um %.2f EUR überschritten' % abs(available)
    procurements = env['x_greenbear.procurement'].search([('x_budget_id', '=', budget.id)])
    procurements.sudo().write({
        'x_available_budget_snapshot': available,
        'x_budget_overrun': overrun,
        'x_budget_note': note,
    })

budget_ids = []
