for order in records:
    procurement = order.x_greenbear_procurement_id
    if procurement and procurement.x_budget_id:
        bindings = env['x_greenbear.precommitment'].search([
            ('x_procurement_id', '=', procurement.id),
            ('x_budget_id', '=', procurement.x_budget_id.id),
            ('x_state', 'in', ['draft', 'active', 'transferred']),
        ], order='id desc', limit=1)
        if order.state in ['purchase', 'done'] and bindings:
            bindings.sudo().write({
                'x_state': 'transferred',
                'x_purchase_order_id': order.id,
                'x_transferred_on': datetime.datetime.now(),
            })
        elif order.state == 'cancel' and bindings and bindings.x_state == 'transferred' and bindings.x_purchase_order_id.id == order.id:
            if procurement.x_state in ['cancelled', 'closed']:
                bindings.sudo().write({
                    'x_state': 'released',
                    'x_released_on': datetime.datetime.now(),
                })
            else:
                bindings.sudo().write({
                    'x_state': 'active',
                    'x_purchase_order_id': False,
                    'x_transferred_on': False,
                })
        elif bindings:
            bindings.sudo().write({'x_amount': bindings.x_amount})
